const input:SemioAudioSnapshot={schema:f.schema,sampleRate:f.sampleRate,format:"f64",channels:f.channels.map(channel=>({samples:channel.map(bits=>({bits}))})),tags:f.tags.map(([key,value])=>({key:key!,value:value!}))};
