/** 🔢️ Native value syntax, owned collections and referential graph cycles. */
import {Database} from "bun:sqlite";
import {expect,test} from "bun:test";
import f from "../../🧫️fixtures/🪶️sqlite/🔣️.json";
import type {SemioValue,SemioValueSnapshot} from "../../🟦️.ts";
import {SEMIO_VALUE_SQLITE_SCHEMA,semioValueSnapshotToSqliteDatabase,semioValueSnapshotFromSqliteDatabase} from "../../🪶️sqlite/🟦️.ts";
import {exportSqliteDatabase,importSqliteDatabase} from "@semio-tech/framework";
const input:SemioValueSnapshot={schema:f.schema,root:{kind:"map",entries:[{key:f.duplicateKey,value:{kind:"list",items:[{kind:"null"},{kind:"bool",value:true},{kind:"int",lexeme:f.integerLexeme},{kind:"float",lexeme:f.floatLexeme},{kind:"str",value:f.string},{kind:"bytes",value:[0,1,127,255]}]}},{key:f.duplicateKey,value:{kind:"ref",id:{value:f.nodeId}}}]},nodes:[{id:{value:f.nodeId},value:{kind:"ref",id:{value:f.nodeId}}}]};
test("Semio value independent typed scalar queries, valid referential cycle and edited string",async()=>{expect(SEMIO_VALUE_SQLITE_SCHEMA).toBe(await Bun.file(new URL("../../🪶️sqlite/🗄️.sql",import.meta.url)).text());const db=Database.deserialize(await exportSqliteDatabase(await semioValueSnapshotToSqliteDatabase(input)));try{expect(db.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});expect(db.query("PRAGMA foreign_key_check").all()).toEqual([]);expect(db.query(f.query).all()).toHaveLength(10);expect(await semioValueSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(input);db.query("UPDATE semio_value_value SET string_value=? WHERE kind='str'").run(f.editedString);const edited=structuredClone(input);if(edited.root.kind!=="map"||edited.root.entries[0]!.value.kind!=="list")throw Error("fixture shape");edited.root.entries[0]!.value.items[4]={kind:"str",value:f.editedString};expect(await semioValueSnapshotFromSqliteDatabase(await importSqliteDatabase(db.serialize()))).toEqual(edited);}finally{db.close();}});
test("Semio value structural cycles, unowned values, variant fields, limits and cancellation",async()=>{const d=await semioValueSnapshotToSqliteDatabase(input);for(const mutate of [(x:any)=>x.tables[1].rows[0].values[2]=1n,(x:any)=>x.tables[4].rows[0].values[4]=x.tables[1].rows[0].rowid,(x:any)=>x.tables[3].rows[0].values[2]=99n,(x:any)=>x.tables[2].rows[0].values[4]=999n,(x:any)=>x.tables[1].rows[x.tables[1].rows.length-1].values[7]=999n]){const x=structuredClone(d);mutate(x);expect(semioValueSnapshotFromSqliteDatabase(x)).rejects.toThrow();}expect(semioValueSnapshotToSqliteDatabase({...input,nodes:[]})).rejects.toThrow();const cyclic:SemioValue={kind:"list",items:[]};cyclic.items.push(cyclic);expect(semioValueSnapshotToSqliteDatabase({schema:"cycle",root:cyclic,nodes:[]})).rejects.toThrow();expect(semioValueSnapshotToSqliteDatabase(input,{maxRows:1})).rejects.toThrow();expect(semioValueSnapshotFromSqliteDatabase(d,{maxValueBytes:1})).rejects.toThrow();let deep:SemioValue={kind:"null"};for(let i=0;i<2000;i++)deep={kind:"list",items:[deep]};const source={schema:"deep",root:deep,nodes:[]};const file=await semioValueSnapshotToSqliteDatabase(source);const result=await semioValueSnapshotFromSqliteDatabase(file);let depth=0,v=result.root;while(v.kind==="list"){depth++;v=v.items[0]!;}expect(depth).toBe(2000);const c=new AbortController();expect(semioValueSnapshotFromSqliteDatabase(file,{signal:c.signal,onProgress:p=>{if(p.completed>=256)c.abort();}})).rejects.toThrow();});
test("quick::Semio value remaining aggregate budget and cancellation precede large byte ownership copies",async()=>{let reads=0;const values=new Proxy(new Array<number>(f.largeBlobBytes).fill(17),{get(target,key,receiver){if(typeof key==="string"&&/^[0-9]+$/.test(key))reads++;return Reflect.get(target,key,receiver);}}),s:SemioValueSnapshot={schema:"large",root:{kind:"bytes",value:values},nodes:[]};await expect(semioValueSnapshotToSqliteDatabase(s,{maxValueBytes:32})).rejects.toThrow();expect(reads).toBe(0);const c=new AbortController();await expect(semioValueSnapshotToSqliteDatabase(s,{signal:c.signal,onProgress:p=>{if(p.phase==="projectSnapshot"&&p.total===f.largeBlobBytes)c.abort();}})).rejects.toThrow();expect(reads).toBe(0);const db=Database.deserialize(await exportSqliteDatabase(await semioValueSnapshotToSqliteDatabase(s)));try{expect(db.query("SELECT length(bytes_value) AS bytes FROM semio_value_value").get()).toEqual({bytes:f.largeBlobBytes});}finally{db.close();}},30000);

test("quick::Semio value native construction frontier matches independent typed entry rows",async()=>{const s:SemioValueSnapshot={schema:f.schema,root:{kind:"list",items:Array.from({length:f.nativeAdmission.collectionItems},()=>({kind:"map",entries:[{key:f.duplicateKey,value:{kind:"bytes",value:[0,255]}}]}))},nodes:[]};const d=Database.deserialize(await exportSqliteDatabase(await semioValueSnapshotToSqliteDatabase(s)));try{expect(d.query("SELECT count(*) AS count FROM semio_value_list_element").get()).toEqual({count:f.nativeAdmission.collectionItems});expect(d.query("SELECT count(*) AS count FROM semio_value_map_entry WHERE member_key=?").get(f.duplicateKey)).toEqual({count:f.nativeAdmission.collectionItems});expect(d.query("SELECT hex(bytes_value) AS bytes FROM semio_value_value WHERE kind='bytes' LIMIT 1").get()).toEqual({bytes:"00FF"});}finally{d.close();}},30000);

